    G=copy.deepcopy(g)
    cr,cc=next((r,c) for r in range(11) for c in range(11) if G[r][c]==3)
    r,c=cr,cc
    dirs=[(-1,0),(0,1),(1,0),(0,-1)]
    for i,L in enumerate([2,2,4,4,6,6,8,8,10,10,12,12]):
        dr,dc=dirs[i%4]
        for k in range(L):
            nr,nc=r+dr,c+dc
            if not (0<=nr<11): nr%=11
            if not (0<=nc<11): nc%=11
            v=G[nr][nc]
            if v==2:
                drr,dcc=nr-cr,nc-cc
                if abs(drr)>abs(dcc): pr,pc=(1 if drr>0 else -1,0)
                elif abs(dcc)>abs(drr): pr,pc=(0,1 if dcc>0 else -1)
                else: pr,pc=(1,0)  # tie -> south
                tr,tc=nr+pr,nc+pc
                if 0<=tr<11 and 0<=tc<11 and G[tr][tc]==0:
                    G[nr][nc]=3; G[tr][tc]=2
                else:
                    if verbose: print(f"block at run{i+1} cell({nr},{nc})")
                    return G
            elif v!=0:
                if verbose: print(f"self-block run{i+1} cell({nr},{nc})")
                return G
            G[nr][nc]=3; r,c=nr,nc
    return G

